!function(a){function i(i){for(var o,t,n=i[0],s=i[1],u=i[2],c=0,g=[];c<n.length;c++)t=n[c],Object.prototype.hasOwnProperty.call(e,t)&&e[t]&&g.push(e[t][0]),e[t]=0;for(o in s)Object.prototype.hasOwnProperty.call(s,o)&&(a[o]=s[o]);for(m&&m(i);g.length;)g.shift()();return p.push.apply(p,u||[]),r()}function r(){for(var a,i=0;i<p.length;i++){for(var r,t=p[i],n=!0,s=1;s<t.length;s++)r=t[s],0!==e[r]&&(n=!1);n&&(p.splice(i--,1),a=o(o.s=t[0]))}return a}function o(i){if(t[i])return t[i].exports;var r=t[i]={i:i,l:!1,exports:{}};return a[i].call(r.exports,r,r.exports,o),r.l=!0,r.exports}var t={},e={13:0},p=[];o.m=a,o.c=t,o.d=function(a,i,r){o.o(a,i)||Object.defineProperty(a,i,{enumerable:!0,get:r})},o.r=function(a){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(a,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(a,"__esModule",{value:!0})},o.t=function(a,i){if(1&i&&(a=o(a)),8&i)return a;if(4&i&&"object"==typeof a&&a&&a.__esModule)return a;var r=Object.create(null);if(o.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:a}),2&i&&"string"!=typeof a)for(var t in a)o.d(r,t,function(i){return a[i]}.bind(null,t));return r},o.n=function(a){var i=a&&a.__esModule?function(){return a.default}:function(){return a};return o.d(i,"a",i),i},o.o=function(a,i){return Object.prototype.hasOwnProperty.call(a,i)},o.p="";var n=window.webpackJsonp=window.webpackJsonp||[],s=n.push.bind(n);n.push=i,n=n.slice();for(var u=0;u<n.length;u++)i(n[u]);var m=s;p.push([107,0]),r()}({107:function(a,i,r){"use strict";r.r(i);var o=r(0);Object(o.a)("us","army",r(108),r(1))},108:function(a){a.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"轻武器","link":"us_army#us_army_iw"}],"model":"“巴祖卡”火箭发射筒","description":"<h6>综述：</h6><p>美军的“巴祖卡”（Bazooka）火箭发射筒是二战中颇有名气的武器，因其外形与一种名叫“巴祖卡”的乐器相似而以此命名。</p><p>“巴祖卡”火箭发射筒是在1942年初由美国研制并装备美军步兵，最初型号是M1（含M1A1）型，1943年底改进后称M9（含M9A1）型。</p><p>“巴祖卡”火箭发射筒首战于1942年底登陆北非的“火炬行动”中。在北非与欧洲战场上，美军主要用来对抗德军的坦克装甲车，但在太平洋海岛战场上，美军更多是用其来攻击日军的工事及掩体。由于该火箭发射筒在二战的欧亚战场上都为美军立下不少战功，因此战后艾森豪威尔将“巴祖卡”连同原子弹、吉普车和C-47运输机并称为四个胜利工具。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_iwBazooka_10.jpg","description":"<h6>“巴祖卡”火箭发射筒</h6><p></p><p>基本技术数据：</p><p>火箭筒口径：60毫米；</p><p>火箭筒长度：1384～1524毫米；</p><p>火箭筒重量：4.48～5.05公斤；</p><p>发射初速：81～91米/秒；</p><p>直射距离：100米；</p><p>有效射程：270米；</p><p>最大射程：360～640米；</p><p>配用弹种：破甲弹，燃烧弹，发烟弹。</p><p>（弹径：60毫米，弹长：410～550毫米，弹重1.52～1.55公斤，炸药重量：288克）</p>","caption":"型号说明：图1为M1；图2为M1A1；图3为M9；图4为M9A1。"}],"part2title":"战场上的“巴祖卡”火箭发射筒","part2description":"","part2content":[{"image":"imgs/us/army/us_army_iwBazooka_20.jpg","description":"（图左）美军第1步兵师一名手持M1A1型火箭发射筒的军士。（图右）在太平洋硫磺岛手持M1A1型火箭发射筒作战的一名美国海军陆战队火箭筒发射手。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_21.jpg","description":"1943年，一名美军正在使用一支早期研制的M1型“巴祖卡”火箭发射筒进行发射训练。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_22.jpg","description":"1944年6月，在西线战场法国诺曼底战役前，M1A1型“巴祖卡”火箭发射筒已大量列装美军，美军主力步兵师平均装备数量达557具。（图左）美国陆军第101空降师的一名装备M1A1型“巴祖卡”火箭发射筒士兵在登上C-47运输机时的照片。当日，数千名盟军士兵将会空降至法国诺曼底地区。（图右）准备登陆法国犹它海滩的美军士兵，其中一名士兵手持M1A1型“巴祖卡”火箭发射筒。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_23.jpg","description":"1944年8月，西线法国战场，美军第5步兵师的士兵跟随一辆M10坦克歼击车沿公路向巴黎进发，其中一名士兵身背的是一支M1A1型“巴祖卡”火箭发射筒。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_24.jpg","description":"1945年3月，由巴顿率领的美国第3集团军在奥本海姆附近渡过莱茵河后，在曼海姆车站附近作战的第94师一支步兵分队正在用M1A1型“巴祖卡”火箭发射筒攻击德军一个楼房工事。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_25.jpg","description":"1944年12月，西线战场，美军一个火箭筒小组持M1A1型“巴祖卡”火箭发射筒击毁了德军一辆黑豹坦克。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_26.jpg","description":"1944年冬，西线战场，美军101工兵营B连一个火箭筒小分队的士兵背着M9A1型“巴祖卡”火箭发射筒行进在森林雪地中。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_27.jpg","description":"绘画：1944年冬季，西线战场阿登地区，在美军构筑的防御阵地中，美军正在拼命抵挡德军进攻，其中一名士兵用M1A1型“巴祖卡”火箭发射筒击毁了一辆德军坦克。早期，“巴祖卡”火箭发射筒发射的火箭弹对60度倾角的装甲的穿透力只有76毫米。后来尽管已提高至102毫米，但此时德军重型坦克的正面装甲与侧裙装甲已装上了更厚的新型铸造装甲，这使得巴祖卡火箭筒只能对准坦克的履带，观察孔，车轮或者是后发动机攻击才能达到击伤或击毁的效果。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_28.jpg","description":"绘画：西线战场美军在阿登地区的反击战，美军用多具M1A1型“巴祖卡”火箭发射筒与德军作战。图中一名美军正在给“巴祖卡”火箭发射筒装填火箭弹，这种火箭弹是一种带尾翼的破甲火箭弹，尽管其有效射程超过100米，但实际作战中，为了提高射击准确率，其射击距离一般都在50米以下。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_29.jpg","description":"1944年6月，太平洋战场塞班岛，美陆军第27步兵师的一个火箭筒小队的一名士兵正持一支M9型“巴祖卡”火箭发射筒向山上的日军碉堡轰击。在太平洋海岛争夺战中，巴祖卡已成为美军攻击摧毁日军混凝土掩体和碉堡的利器。M9与M9A1型“巴祖卡”火箭发射筒安装有光学与机械瞄准器，相比M1A1型大大提高了射击准确率，而该火箭筒平时可拆分开两部份，因此也方便了携带。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_30.jpg","description":"二战太平洋战场，美陆军士兵正持一支M9A1型“巴祖卡”火箭发射筒向日军工事轰击。图中可见，“巴祖卡”火箭发射筒发射时尾焰很大，很容易会做成误伤。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_31.jpg","description":"1944年7月，太平洋战场塞班岛，美国海军陆战队一名士兵正手持一支M1A1型“巴祖卡”火箭发射筒向日军工事轰击。在太平洋战场上，当时美陆军步兵已装备M9A1型“巴祖卡”火箭发射筒，但美海军陆战队使用的“巴祖卡”仍多为M1A1型。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_32.jpg","description":"二战太平洋战场，正在冲绳岛作战的美陆军士兵正在使用一支M9A1型“巴祖卡”火箭发射筒瞄准日军工事，随时准备进行攻击。","caption":""},{"image":"imgs/us/army/us_army_iwBazooka_33.jpg","description":"绘画：二战太平洋战场，塞班岛，手持M1A1型“巴祖卡”火箭发射筒与日军作战的美国海军陆战队士兵。","caption":""}]}')}});